M = (B + C)/2;

draw(O--A,dashed);
draw(O--B,dashed);
draw(O--C,dashed);
draw(O--D,dashed);
draw(A--B--D--C--cycle);
draw(B--C);
draw(A--M);
draw(M--O,dashed);

label("$A$", A, N);
